CREATE TABLE IF NOT EXISTS aircraft (id INT AUTO_INCREMENT PRIMARY KEY, registration VARCHAR(30) NOT NULL UNIQUE, model VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS maintenance_tasks (id INT AUTO_INCREMENT PRIMARY KEY, aircraft_id INT NOT NULL, title VARCHAR(200) NOT NULL, due_date DATE NOT NULL, status ENUM('OPEN','IN_PROGRESS','COMPLETED') NOT NULL DEFAULT 'OPEN', FOREIGN KEY (aircraft_id) REFERENCES aircraft(id));
CREATE TABLE IF NOT EXISTS inspections (id INT AUTO_INCREMENT PRIMARY KEY, aircraft_id INT NOT NULL, result ENUM('PASS','FAIL') NOT NULL, notes VARCHAR(1000), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (aircraft_id) REFERENCES aircraft(id));
